"""Vault encryption backends.

The vault uses AES-256-GCM to encrypt record blobs at rest.
The compact wire format is: base64(nonce) + "." + base64(ciphertext || tag)

Two backends are available:
- LocalFileCrypto: master key stored in ~/.authsome/server/master.key (mode 0600)
- KeyringCrypto: master key stored in the OS keyring
"""

from __future__ import annotations

import base64
import json
import os
import secrets
from abc import ABC, abstractmethod
from pathlib import Path

from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from loguru import logger

from authsome.errors import EncryptionUnavailableError

_KEY_SIZE_BYTES = 32  # 256-bit
_NONCE_SIZE_BYTES = 12  # 96-bit for AES-GCM
_KEYRING_SERVICE = "authsome"
_KEYRING_USERNAME = "master_key"
_MASTER_KEY_ENV_VAR = "AUTHSOME_MASTER_KEY"


class VaultCrypto(ABC):
    """Protocol for vault-level encryption backends."""

    @property
    @abstractmethod
    def source_id(self) -> str:
        """Stable identifier for the effective master-key source."""
        ...

    @property
    @abstractmethod
    def source_description(self) -> str:
        """Human-readable description of the effective master-key source."""
        ...

    @abstractmethod
    def encrypt(self, plaintext: str) -> str:
        """Encrypt plaintext and return a compact ciphertext string."""
        ...

    @abstractmethod
    def decrypt(self, ciphertext: str) -> str:
        """Decrypt a compact ciphertext string and return plaintext."""
        ...


def _encode(nonce: bytes, ct_with_tag: bytes) -> str:
    """Pack nonce + ciphertext+tag into a single dot-separated base64 string."""
    return base64.b64encode(nonce).decode("ascii") + "." + base64.b64encode(ct_with_tag).decode("ascii")


def _decode(token: str) -> tuple[bytes, bytes]:
    """Unpack a dot-separated base64 string into (nonce, ciphertext+tag)."""
    try:
        nonce_b64, ct_b64 = token.split(".", 1)
        return base64.b64decode(nonce_b64), base64.b64decode(ct_b64)
    except Exception as exc:
        raise EncryptionUnavailableError(f"Malformed vault ciphertext: {exc}") from exc


class _AesGcmCrypto(VaultCrypto):
    """Base class for AES-GCM encryption backends."""

    def __init__(self, master_key: bytes) -> None:
        if len(master_key) != _KEY_SIZE_BYTES:
            raise EncryptionUnavailableError(
                f"Master key must be {_KEY_SIZE_BYTES} bytes after base64 decoding; got {len(master_key)} bytes."
            )
        self._aesgcm = AESGCM(master_key)

    def encrypt(self, plaintext: str) -> str:
        nonce = secrets.token_bytes(_NONCE_SIZE_BYTES)
        ct_with_tag = self._aesgcm.encrypt(nonce, plaintext.encode("utf-8"), None)
        return _encode(nonce, ct_with_tag)

    def decrypt(self, ciphertext: str) -> str:
        nonce, ct_with_tag = _decode(ciphertext)
        try:
            return self._aesgcm.decrypt(nonce, ct_with_tag, None).decode("utf-8")
        except Exception as exc:
            raise EncryptionUnavailableError(f"Decryption failed: {exc}") from exc


class LocalFileCrypto(_AesGcmCrypto):
    """AES-256-GCM with master key stored as a local file."""

    def __init__(self, key_file: Path) -> None:
        self._key_file = key_file
        super().__init__(self._load_key())

    @property
    def source_id(self) -> str:
        return "local_key"

    @property
    def source_description(self) -> str:
        return f"Local File ({self._key_file})"

    def _load_key(self) -> bytes:
        if self._key_file.exists():
            try:
                key_data = json.loads(self._key_file.read_text(encoding="utf-8"))
                return _decode_master_key(key_data["key"], f"local key file {self._key_file}")
            except (json.JSONDecodeError, KeyError, ValueError) as exc:
                raise EncryptionUnavailableError(f"Failed to read local key file {self._key_file}: {exc}") from exc

        master_key = _new_master_key()
        self._key_file.parent.mkdir(parents=True, exist_ok=True)
        key_data = {
            "version": 1,
            "key": base64.b64encode(master_key).decode("ascii"),
            "algorithm": "AES-256-GCM",
            "note": "Local master key for authsome. Protect this file.",
        }
        self._key_file.write_text(json.dumps(key_data, indent=2), encoding="utf-8")
        try:
            os.chmod(self._key_file, 0o600)
        except OSError:
            pass
        logger.info("Generated new master key at {}", self._key_file)
        return master_key


class KeyringCrypto(_AesGcmCrypto):
    """AES-256-GCM with master key stored in the OS keyring."""

    def __init__(self, master_key: bytes | None = None) -> None:
        super().__init__(master_key or self._load_key())

    @property
    def source_id(self) -> str:
        return "keyring"

    @property
    def source_description(self) -> str:
        return "OS Keyring"

    def _load_key(self) -> bytes:
        master_key = _get_keyring_key(create_if_missing=True, strict=True)
        if master_key is None:
            raise EncryptionUnavailableError("OS keyring is unavailable and no master key could be created.")
        return master_key


class EnvVarCrypto(_AesGcmCrypto):
    """AES-256-GCM with master key supplied via AUTHSOME_MASTER_KEY."""

    def __init__(self) -> None:
        super().__init__(self._load_key())

    @property
    def source_id(self) -> str:
        return "env"

    @property
    def source_description(self) -> str:
        return f"Environment Variable ({_MASTER_KEY_ENV_VAR})"

    def _load_key(self) -> bytes:
        raw_value = os.environ.get(_MASTER_KEY_ENV_VAR)
        if raw_value is None:
            raise EncryptionUnavailableError(f"{_MASTER_KEY_ENV_VAR} is not set.")
        if not raw_value.strip():
            raise EncryptionUnavailableError(f"{_MASTER_KEY_ENV_VAR} is set but empty.")
        return _decode_master_key(raw_value.strip(), _MASTER_KEY_ENV_VAR)


def _new_master_key() -> bytes:
    """Generate a new 256-bit master key."""
    return secrets.token_bytes(_KEY_SIZE_BYTES)


def _decode_master_key(encoded_value: str, source: str) -> bytes:
    """Decode and validate a base64-encoded master key."""
    try:
        master_key = base64.b64decode(encoded_value, validate=True)
    except (ValueError, TypeError) as exc:
        raise EncryptionUnavailableError(f"Failed to decode master key from {source}: {exc}") from exc
    if len(master_key) != _KEY_SIZE_BYTES:
        raise EncryptionUnavailableError(
            f"Master key from {source} must decode to {_KEY_SIZE_BYTES} bytes; got {len(master_key)} bytes."
        )
    return master_key


def _get_keyring_key(*, create_if_missing: bool, strict: bool) -> bytes | None:
    """Load a key from the OS keyring, optionally creating it when absent."""
    try:
        import keyring as kr
    except ImportError as exc:
        if strict:
            raise EncryptionUnavailableError(
                "The 'keyring' package is required for keyring mode. Install it with: pip install keyring"
            ) from exc
        return None

    try:
        key_b64 = kr.get_password(_KEYRING_SERVICE, _KEYRING_USERNAME)
    except Exception as exc:
        if strict:
            raise EncryptionUnavailableError(
                f"Failed to access OS keyring: {exc}. Use encryption mode 'local_key' for headless environments."
            ) from exc
        return None

    if key_b64:
        return _decode_master_key(key_b64, "OS keyring")
    if not create_if_missing:
        return None

    master_key = _new_master_key()
    key_b64_str = base64.b64encode(master_key).decode("ascii")
    try:
        kr.set_password(_KEYRING_SERVICE, _KEYRING_USERNAME, key_b64_str)
    except Exception as exc:
        if strict:
            raise EncryptionUnavailableError(
                f"Failed to store master key in OS keyring: {exc}. "
                "Use encryption mode 'local_key' for headless environments."
            ) from exc
        return None
    logger.info("Generated and stored new master key in OS keyring")
    return master_key


def _has_env_master_key() -> bool:
    """Return whether AUTHSOME_MASTER_KEY is present in the environment."""
    return _MASTER_KEY_ENV_VAR in os.environ


def _create_auto_crypto(key_file: Path | None) -> VaultCrypto:
    """Resolve master keys by strength while preserving existing local installs."""
    if _has_env_master_key():
        return EnvVarCrypto()

    existing_keyring_key = _get_keyring_key(create_if_missing=False, strict=False)
    if existing_keyring_key is not None:
        return KeyringCrypto(existing_keyring_key)

    if key_file is None:
        raise ValueError("key_file is required for auto mode fallback")
    if key_file.exists():
        return LocalFileCrypto(key_file)

    created_keyring_key = _get_keyring_key(create_if_missing=True, strict=False)
    if created_keyring_key is not None:
        return KeyringCrypto(created_keyring_key)

    return LocalFileCrypto(key_file)


def create_crypto(key_file: Path | None, mode: str = "auto") -> VaultCrypto:
    """Factory: return the appropriate VaultCrypto backend for the given mode."""
    if mode == "auto":
        return _create_auto_crypto(key_file)
    if mode == "keyring":
        return KeyringCrypto()
    if mode == "env":
        return EnvVarCrypto()
    if key_file is None:
        raise ValueError("key_file is required for 'local_key' mode")
    return LocalFileCrypto(key_file)

"""Concrete local dependency wiring for the daemon server."""

from __future__ import annotations

import os
import secrets
from pathlib import Path
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from authsome.server.credential_service import AuthService
    from authsome.store.interfaces import AppStore

from authsome.auth.models.config import ServerConfig
from authsome.identity import current_from_home
from authsome.paths import get_authsome_home as _get_authsome_home
from authsome.paths import get_server_home as _get_server_home
from authsome.paths import get_server_log_path as _get_server_log_path
from authsome.server.hosted_auth import HostedAccountService
from authsome.server.identity_bootstrap import (
    HostedIdentityBootstrapService,
    IdentityBootstrapService,
    LocalIdentityBootstrapService,
)
from authsome.server.ownership import HostedOwnershipResolver, LocalOwnershipResolver, OwnershipResolver
from authsome.server.registries import (
    IdentityClaimRegistry,
    IdentityRegistry,
    PrincipalRegistry,
    PrincipalVaultBindingRegistry,
    VaultRegistry,
)
from authsome.server.urls import build_server_base_url
from authsome.store.local import LocalAppStore
from authsome.vault import Vault


def get_authsome_home() -> Path:
    """Return the local Authsome home directory."""
    return _get_authsome_home()


def get_server_home(home: Path | None = None) -> Path:
    """Return the daemon-owned state directory."""
    return _get_server_home(home)


def get_server_config_path(home: Path | None = None) -> Path:
    """Return the daemon-owned config file path."""
    return get_server_home(home) / "config.json"


def get_server_log_path(home: Path | None = None) -> Path:
    """Return the daemon-owned structured log path."""
    return _get_server_log_path(home)


def get_identity_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned identity registry file path."""
    return get_server_home(home) / "identity_registry.json"


def get_principal_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned principal registry file path."""
    return get_server_home(home) / "principal_registry.json"


def get_vault_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned vault registry file path."""
    return get_server_home(home) / "vault_registry.json"


def get_identity_claim_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned identity-claim registry file path."""
    return get_server_home(home) / "identity_claim_registry.json"


def get_principal_vault_binding_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned principal-vault binding registry file path."""
    return get_server_home(home) / "principal_vault_binding_registry.json"


def get_ui_session_secret_path(home: Path | None = None) -> Path:
    """Return the hosted UI session signing-secret path."""
    return get_server_home(home) / "ui_session_secret.key"


def get_server_base_url() -> str:
    """Return the daemon's canonical external base URL."""
    return build_server_base_url()


def get_deployment_mode() -> str:
    """Return the daemon deployment mode."""
    mode = os.environ.get("AUTHSOME_DEPLOYMENT_MODE", "local").strip().lower()
    return "hosted" if mode == "hosted" else "local"


def load_ui_session_signing_secret(home: Path | None = None) -> str:
    """Load or create the hosted UI session signing secret."""
    path = get_ui_session_secret_path(home)
    try:
        return path.read_text(encoding="utf-8").strip()
    except FileNotFoundError:
        path.parent.mkdir(parents=True, exist_ok=True)
        secret = secrets.token_hex(32)
        path.write_text(secret, encoding="utf-8")
        os.chmod(path, 0o600)
        return secret


async def get_local_ui_identity(home: Path | None = None) -> str:
    """Resolve the local active identity handle for the server-rendered UI."""
    identity = await current_from_home(home or get_authsome_home())
    return identity.handle


def load_server_config(home: Path | None = None) -> ServerConfig:
    """Load daemon-owned server config, defaulting when absent or invalid."""
    path = get_server_config_path(home)
    try:
        return ServerConfig.model_validate_json(path.read_text(encoding="utf-8"))
    except Exception:
        config = ServerConfig()
        save_server_config(config, home)
        return config


def save_server_config(config: ServerConfig, home: Path | None = None) -> None:
    """Persist daemon-owned server config."""
    path = get_server_config_path(home)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(config.model_dump_json(indent=2), encoding="utf-8")


async def create_app_store(home: Path | None = None) -> AppStore:
    """Create the daemon application store."""
    resolved_home = home or get_authsome_home()
    load_server_config(resolved_home)
    app_store = LocalAppStore(resolved_home)
    await app_store.ensure_initialized()
    return app_store


async def list_registered_identity_handles(home: Path | None = None) -> list[str]:
    """Return identity handles registered with this daemon."""
    registry = IdentityRegistry(get_identity_registry_path(home))
    return await registry.list_handles()


async def create_vault(app_store: AppStore) -> Vault:
    """Create the daemon vault from an initialized application store."""
    resolved_home = app_store.home
    config = load_server_config(resolved_home)
    return Vault(
        app_store=app_store,
        crypto_mode=config.encryption.mode,
        master_key_path=get_server_home(resolved_home) / "master.key",
    )


async def create_auth_service(
    home: Path | None = None, identity: str | None = None, vault_id: str | None = None
) -> AuthService:
    """Create an auth service scoped to an identity handle and an explicit vault_id."""
    from authsome.server.credential_service import AuthService

    if not identity:
        raise ValueError("create_auth_service requires an explicit identity handle")
    if not vault_id:
        raise ValueError("create_auth_service requires an explicit vault_id")
    store = await create_app_store(home)
    vault = await create_vault(store)
    return AuthService(vault=vault, identity=identity, vault_id=vault_id, deployment_mode=get_deployment_mode())


def create_principal_registry(home: Path | None = None) -> PrincipalRegistry:
    return PrincipalRegistry(get_principal_registry_path(home))


def create_vault_registry(home: Path | None = None) -> VaultRegistry:
    return VaultRegistry(get_vault_registry_path(home))


def create_identity_claim_registry(home: Path | None = None) -> IdentityClaimRegistry:
    return IdentityClaimRegistry(get_identity_claim_registry_path(home))


def create_principal_vault_binding_registry(home: Path | None = None) -> PrincipalVaultBindingRegistry:
    return PrincipalVaultBindingRegistry(get_principal_vault_binding_registry_path(home))


def create_hosted_account_service(home: Path | None = None) -> HostedAccountService:
    resolved_home = home or get_authsome_home()
    return HostedAccountService(
        principals=create_principal_registry(resolved_home),
        vaults=create_vault_registry(resolved_home),
        bindings=create_principal_vault_binding_registry(resolved_home),
        jwt_secret=load_ui_session_signing_secret(resolved_home),
    )


def create_ownership_resolver(home: Path | None = None) -> OwnershipResolver:
    resolved_home = home or get_authsome_home()
    principals = create_principal_registry(resolved_home)
    vaults = create_vault_registry(resolved_home)
    claims = create_identity_claim_registry(resolved_home)
    bindings = create_principal_vault_binding_registry(resolved_home)
    if get_deployment_mode() == "hosted":
        return HostedOwnershipResolver(
            principals=principals,
            vaults=vaults,
            claims=claims,
            bindings=bindings,
        )
    return LocalOwnershipResolver(
        principals=principals,
        vaults=vaults,
        bindings=bindings,
    )


def create_identity_bootstrap_service(
    identity_registry: IdentityRegistry,
    ui_sessions: Any,
    *,
    home: Path | None = None,
    server_base_url: str | None = None,
) -> IdentityBootstrapService:
    resolved_home = home or get_authsome_home()
    if get_deployment_mode() == "hosted":
        return HostedIdentityBootstrapService(
            registry=identity_registry,
            claims=create_identity_claim_registry(resolved_home),
            ui_sessions=ui_sessions,
            server_base_url=server_base_url or get_server_base_url(),
        )
    return LocalIdentityBootstrapService(registry=identity_registry)

