    raw_kv = app_store.kv
    secret = MasterSecretResolver(app_store.server_home).resolve()
    dek = await DekManager().load_or_create(secret, raw_kv)
    encrypted_kv = AesGcmEncryptionWrapper(raw_kv, dek=dek)
    return Vault(encrypted_kv)


